using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using UAF.Domain.Entities;
using UAF.Infrastructure.Identity;
namespace UAF.Infrastructure.Persistence.Configurations;
public sealed class NotificationConfiguration:IEntityTypeConfiguration<Notification>{public void Configure(EntityTypeBuilder<Notification>b){b.ToTable("Notifications");b.HasKey(x=>x.Id);b.Property(x=>x.Title).HasMaxLength(160).IsRequired();b.Property(x=>x.Message).HasMaxLength(4000).IsRequired();b.Property(x=>x.Channel).HasConversion<int>();b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.FailureReason).HasMaxLength(500);b.HasIndex(x=>new{x.RecipientUserId,x.Channel,x.Status,x.CreatedAtUtc});b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.RecipientUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class WorkflowInstanceConfiguration:IEntityTypeConfiguration<WorkflowInstance>{public void Configure(EntityTypeBuilder<WorkflowInstance>b){b.ToTable("WorkflowInstances");b.HasKey(x=>x.Id);b.Property(x=>x.ResourceType).HasMaxLength(100).IsRequired();b.Property(x=>x.Status).HasConversion<int>();b.HasIndex(x=>new{x.ResourceType,x.ResourceId,x.Status});b.HasIndex(x=>new{x.ResourceType,x.ResourceId}).IsUnique().HasFilter("[Status] = 1");b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.RequestedByUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class WorkflowApprovalStepConfiguration:IEntityTypeConfiguration<WorkflowApprovalStep>{public void Configure(EntityTypeBuilder<WorkflowApprovalStep>b){b.ToTable("WorkflowApprovalSteps");b.HasKey(x=>x.Id);b.Property(x=>x.RequiredRole).HasMaxLength(100).IsRequired();b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.Comments).HasMaxLength(2000);b.HasIndex(x=>new{x.WorkflowInstanceId,x.Sequence}).IsUnique();b.HasOne<WorkflowInstance>().WithMany().HasForeignKey(x=>x.WorkflowInstanceId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.AssignedUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.DecidedByUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class WorkflowHistoryConfiguration:IEntityTypeConfiguration<WorkflowHistory>{public void Configure(EntityTypeBuilder<WorkflowHistory>b){b.ToTable("WorkflowHistory");b.HasKey(x=>x.Id);b.Property(x=>x.ResourceType).HasMaxLength(100).IsRequired();b.Property(x=>x.FromState).HasMaxLength(50).IsRequired();b.Property(x=>x.ToState).HasMaxLength(50).IsRequired();b.Property(x=>x.Comments).HasMaxLength(2000);b.HasIndex(x=>new{x.WorkflowInstanceId,x.OccurredAtUtc});b.HasOne<WorkflowInstance>().WithMany().HasForeignKey(x=>x.WorkflowInstanceId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.ActorUserId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class AuditTrailEntryConfiguration:IEntityTypeConfiguration<AuditTrailEntry>{public void Configure(EntityTypeBuilder<AuditTrailEntry>b){b.ToTable("AuditTrailEntries");b.HasKey(x=>x.Id);b.Property(x=>x.Action).HasMaxLength(30).IsRequired();b.Property(x=>x.EntityType).HasMaxLength(150).IsRequired();b.Property(x=>x.CorrelationId).HasMaxLength(100);b.Property(x=>x.RemoteIp).HasMaxLength(64);b.Property(x=>x.BeforeJson).HasColumnType("nvarchar(max)");b.Property(x=>x.AfterJson).HasColumnType("nvarchar(max)");b.HasIndex(x=>new{x.EntityType,x.EntityId,x.OccurredAtUtc});b.HasIndex(x=>new{x.ActorUserId,x.OccurredAtUtc});b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.ActorUserId).OnDelete(DeleteBehavior.Restrict);}}
